@staticmethod
def no_smooth(numerators: torch.Tensor, denominators: torch.Tensor) -> Sequence[float]:
    denominators_ = [max(1, d) for d in denominators]
    return [n.item() / d for n, d in zip(numerators, denominators_)]

@staticmethod
def smooth1(numerators: torch.Tensor, denominators: torch.Tensor) -> Sequence[float]:
    epsilon = 0.1
    denominators_ = [max(1, d.item()) for d in denominators]
    return [n.item() / d if n != 0 else epsilon / d for n, d in zip(numerators, denominators_)]

@staticmethod
def smooth2(numerators: torch.Tensor, denominators: torch.Tensor) -> Sequence[float]:
    return _Smoother._smooth2(numerators, denominators)

def __call__(self, engine: Engine) -> None:
    output = self._output_transform(engine.state.output)

    def raise_error(x: float | torch.Tensor) -> None:
        if isinstance(x, numbers.Number):
            x = torch.tensor(x)

        if isinstance(x, torch.Tensor) and not bool(torch.isfinite(x).all()):
            raise RuntimeError("Infinite or NaN tensor found.")

    try:
        apply_to_type(output, (numbers.Number, torch.Tensor), raise_error)
    except RuntimeError:
        self.logger.warning(f"{self.__class__.__name__}: Output '{output}' contains NaN or Inf. Stop training")
        engine.terminate()

@staticmethod
def _compute_f_score(precision, recall, alpha=0.5):
    return (
        0.0
        if (recall == 0.0 or precision == 0.0)
        else precision * recall / ((1 - alpha) * precision + alpha * recall)
    )

@sync_all_reduce("_sum_of_squared_errors", "_num_examples")
def compute(self) -> float | torch.Tensor:
    if self._num_examples == 0:
        raise NotComputableError("MeanSquaredError must have at least one example before it can be computed.")
    return self._sum_of_squared_errors.item() / self._num_examples

def __call__(self, engine: Engine) -> None:
    score = self.score_function(engine)

    if self.best_score is None:
        self.best_score = score
        return

    threshold = -self.threshold if self.mode == "min" else self.threshold
    if self.threshold_mode == "abs":
        improvement_threshold = self.best_score + threshold
    else:
        improvement_threshold = self.best_score * (1 + threshold)

    no_improvement = score <= improvement_threshold if self.mode == "max" else score >= improvement_threshold

    if no_improvement:
        if not self.cumulative:
            self.best_score = max(score, self.best_score) if self.mode == "max" else min(score, self.best_score)
        self.counter += 1
        self.logger.debug("EarlyStopping: %i / %i" % (self.counter, self.patience))
        if self.counter >= self.patience:
            self.logger.info("EarlyStopping: Stop training")
            self.trainer.terminate()
    else:
        self.best_score = score
        self.counter = 0

def __call__(self, engine: Engine) -> None:
    elapsed_time = time.perf_counter() - self.start_time
    if elapsed_time > self.limit_sec:
        self.logger.info(f"Reached the time limit: {self.limit_sec} sec. Stop training")
        engine.terminate()

@sync_all_reduce("confusion_matrix", "_num_examples")
def compute(self) -> torch.Tensor:
    if self._num_examples == 0:
        raise NotComputableError("Confusion matrix must have at least one example before it can be computed.")
    if self.average:
        self.confusion_matrix = self.confusion_matrix.float()
        if self.average == "samples":
            return self.confusion_matrix / self._num_examples
        else:
            return self.normalize(self.confusion_matrix, self.average)
    return self.confusion_matrix
